import bpy, sys, json, os
from mathutils import Vector

args = sys.argv[sys.argv.index('--') + 1:]
src, out_json, tex_dir = args[0], args[1], args[2]
os.makedirs(tex_dir, exist_ok=True)
bpy.ops.wm.open_mainfile(filepath=src)

def sock_val(s):
    try:
        v = s.default_value
        if hasattr(v, '__iter__') and not isinstance(v, str):
            return [round(float(x), 5) for x in v]
        return round(float(v), 5)
    except Exception:
        return str(getattr(s, 'default_value', None))

result = {'filepath': src}
group = bpy.data.node_groups['Weapon_Element_Color']
result['element_group'] = []
for n in group.nodes:
    rec = {'name': n.name, 'type': n.type, 'label': n.label}
    if n.type == 'RGB':
        rec['color'] = sock_val(n.outputs[0])
    result['element_group'].append(rec)

mat = bpy.data.materials['V4_element_emission']
result['v4_nodes'] = []
for n in mat.node_tree.nodes:
    rec = {'name': n.name, 'type': n.type, 'label': n.label}
    if n.type in ('VALUE', 'RGB'):
        rec['value'] = sock_val(n.outputs[0])
    if n.type == 'MATH':
        rec['op'] = n.operation
        rec['in0'] = sock_val(n.inputs[0])
        rec['in1'] = sock_val(n.inputs[1])
    if n.type == 'BSDF_PRINCIPLED':
        rec['emission_color'] = sock_val(n.inputs['Emission Color'])
        rec['emission_strength'] = sock_val(n.inputs['Emission Strength'])
        rec['metallic'] = sock_val(n.inputs['Metallic'])
        rec['roughness'] = sock_val(n.inputs['Roughness'])
        rec['linked'] = {i.name: [l.from_node.name, l.from_node.label, l.from_socket.name] for i in n.inputs for l in i.links}
    result['v4_nodes'].append(rec)
result['v4_links'] = [[l.from_node.name, l.from_node.label, l.from_socket.name, l.to_node.name, l.to_socket.name] for l in mat.node_tree.links]

body = bpy.data.materials[0] if False else bpy.data.objects['Body_original_mesh'].data.materials[0]
bsdf = next(n for n in body.node_tree.nodes if n.type == 'BSDF_PRINCIPLED')
result['body_pbr_links'] = {i.name: [[l.from_node.name, l.from_node.type, l.from_socket.name] for l in i.links] for i in bsdf.inputs if i.links}
result['body_images'] = []
for n in body.node_tree.nodes:
    if n.type == 'TEX_IMAGE' and n.image:
        result['body_images'].append({'node': n.name, 'image': n.image.name, 'cs': n.image.colorspace_settings.name, 'alpha': n.image.alpha_mode})

# energy cell bounds and generated-X used by fill
cells = bpy.data.objects['V4_energy_cells']
bbs = [cells.matrix_world @ Vector(c) for c in cells.bound_box]
result['energy_cells_world_bounds'] = {
    'min': [round(min(v[i] for v in bbs), 5) for i in range(3)],
    'max': [round(max(v[i] for v in bbs), 5) for i in range(3)],
}
# second segment if duplicated
if 'V4_energy_cells' in bpy.data.objects:
    pass
dupes = [o.name for o in bpy.data.objects if 'energy' in o.name.lower() or 'V4_' in o.name]
result['v4_objects'] = dupes

# export packed textures once
for im in bpy.data.images:
    if im.packed_file and im.size[0] > 0 and im.name.startswith(('Color_', 'ORM_', 'NormalGL_')):
        path = os.path.join(tex_dir, im.name + '.png')
        im.filepath_raw = path
        im.file_format = 'PNG'
        im.save()
        result.setdefault('exported', []).append(path)

with open(out_json, 'w', encoding='utf8') as f:
    json.dump(result, f, indent=2)
print('WROTE', out_json)
print('ELEMENT', result['element_group'])
print('V4', [(n['label'], n.get('value'), n.get('op')) for n in result['v4_nodes']])
print('PBR', result['body_pbr_links'])
print('CELLS', result['energy_cells_world_bounds'])

import bpy, sys, collections
from mathutils import Vector
args = sys.argv[sys.argv.index('--') + 1:]
bpy.ops.wm.open_mainfile(filepath=args[0])
body = bpy.data.objects['Body_original_mesh']
mats = [s.material.name if s.material else None for s in body.material_slots]
print('TRIGGER', bpy.data.objects['Trigger_Complete_Moving'].data.materials[:], 'faces', len(bpy.data.objects['Trigger_Complete_Moving'].data.polygons))
for o in bpy.data.objects:
    if o.name.startswith('V4_') or 'Front' in o.name:
        bb = [o.matrix_world @ Vector(c) for c in o.bound_box]
        print(o.name, 'loc', [round(v,4) for v in o.location], 'bounds', [[round(min(v[i] for v in bb),4), round(max(v[i] for v in bb),4)] for i in range(3)])
regions = {
    'muzzle_plate': lambda c: -0.48 < c.x < -0.30 and c.y < -0.02 and 0.10 < c.z < 0.26,
    'trigger_stamp': lambda c: 0.02 < c.x < 0.20 and c.y < -0.02 and 0.03 < c.z < 0.10,
    'front_housing_text': lambda c: -0.20 < c.x < -0.02 and c.y < 0 and 0.12 < c.z < 0.22,
}
for name, pred in regions.items():
    hits = collections.Counter()
    samples = []
    for p in body.data.polygons:
        c = body.matrix_world @ p.center
        if pred(c):
            hits[mats[p.material_index]] += 1
            if len(samples) < 8:
                samples.append(([round(c.x,4), round(c.y,4), round(c.z,4)], mats[p.material_index]))
    print(name, dict(hits), 'samples', samples)
# leftover cyan-looking emission: faces still tripo near optic inner posts
optic_inner = 0
for p in body.data.polygons:
    c = body.matrix_world @ p.center
    if 0.08 < c.x < 0.16 and abs(c.y) < 0.055 and 0.33 < c.z < 0.38:
        if mats[p.material_index] and 'tripo' in mats[p.material_index]:
            optic_inner += 1
print('optic_inner_tripo_faces', optic_inner)

const http = require('http');
const fs = require('fs');
const path = require('path');
const root = __dirname;
const types = { '.png': 'image/png', '.html': 'text/html; charset=utf-8' };
http.createServer((req, res) => {
  const url = decodeURIComponent(req.url.split('?')[0]);
  const rel = url === '/' ? 'gallery.html' : url.replace(/^\/+/, '');
  const file = path.join(root, rel);
  if (!file.startsWith(root)) {
    res.writeHead(403);
    res.end('forbidden');
    return;
  }
  fs.readFile(file, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end('not found');
      return;
    }
    res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream' });
    res.end(data);
  });
}).listen(8765, '127.0.0.1', () => {
  console.log('SERVING http://127.0.0.1:8765/');
});
